function BeginnerAssembleTaskPanel:__init()
    self.isStarting = true
    self.isSwitching = false
    self.startTime = os.time()
    self.previewIndex = 1
    self.maxNo = 1 ---皮肤最大值
    self.slideShowCo = nil
    self.selectDayNum = nil --七日任务选择的天数
end

function BeginnerAssembleTaskPanel:__delete()

end

function BeginnerAssembleTaskPanel:Awake()
    CfUtils.SetActive(self.LeftGroup, false)
    CfUtils.SetActive(self.MainTaskCellGroup, false)
end

function BeginnerAssembleTaskPanel:Start()
    self.controller:StartCoroutine(util.cs_generator(function()
        while self.isStarting do
            --coroutine.yield(CoYield(3))
            while os.time() - self.startTime <= 3 do
                coroutine.yield()
            end
            self.startTime = os.time()
            while self.isSwitching do
                coroutine.yield()
            end
            if self.maxNo > 1 then
                self.previewIndex = self.previewIndex - 1
                if self.previewIndex < 1 then
                    self.previewIndex = self.maxNo
                end
                ---自动切下一个
                self:OnSwitchNext()
            end
        end
    end))
end

