function BeginnerAssembleTaskPanel:FreshTaskView()
    ---@type BeginnerMgr
    local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
    local groups = beginnerMgr:GetTaskGroups()
    if isNull(self.selectDayNum) then
        self.selectDayNum = math.min(beginnerMgr:GetHomeDojo().todayNum, #groups)
    end
    KTool.DestroyGameObjectChildren(self.LayoutDayGroup.gameObject)
    local todayNum = checkNumber(beginnerMgr:GetHomeDojo().todayNum)
    for i = 1, #groups do
        local dayGo
        if i == #groups then
            dayGo = CfUtils.InstantiateGo(self.BtnDaySevenNode, self.LayoutDayGroup)
        else
            dayGo = CfUtils.InstantiateGo(self.BtnDayNode, self.LayoutDayGroup)
        end
        dayGo.name = "DayGo" .. i
        ---@type BeginnerSevenDayCellNode
        local dayGoEnv = CfUtils.GetLuaScr(dayGo, "Game.UI.BeginnerEvent.BeginnerSevenDayCellNode")
        local pro, max = beginnerMgr:GetTaskGroupProgress(i)
        CfUtils.SetActive(dayGo, true)
        dayGoEnv:FreshBaseUI({
            progress = pro,
            count = max,
            day = i,
            isOpened = i <= todayNum
        }, todayNum, i == self.selectDayNum, #groups, beginnerMgr:IsTaskCompleted(), checkNumber(beginnerMgr:GetHomeDojo().drawnFinalPrize), true)
        dayGoEnv:UpdateRedPointStatus(beginnerMgr:HasRedPointGroupByDay(i))
        dayGoEnv:SetBtnCallBack(function()
            if i ~= self.selectDayNum then
                if i <= todayNum then
                    if beginnerMgr:IsTaskCompleted() and checkNumber(beginnerMgr:GetHomeDojo().drawnFinalPrize) == 0 then
                        ---任务全完成并且奖励未领取的情况下
                        GameUtils.Request(Interfaces.ActivityBeginnerDrawFinalReward, { prizeId = 1 }, function(request, response)
                            if checkInt(response.errCode) == 0 then
                                local data = response.data
                                GoodsUtils.DrawRewards(data.rewards)
                                beginnerMgr:GetHomeDojo().drawnFinalPrize = 1
                                self:FreshRedPoint()
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                                self:FreshTaskView()
                            end
                        end)
                    else
                        ---@type BeginnerSevenDayCellNode
                        local preEnv = self:GetDayCellEnv(self.selectDayNum)
                        if preEnv then
                            preEnv:FreshSelectStatus(false)
                            preEnv:PlayAnimation(false)
                        end
                        self.selectDayNum = i
                        ---@type BeginnerSevenDayCellNode
                        local preEnv = self:GetDayCellEnv(self.selectDayNum)
                        if preEnv then
                            preEnv:FreshSelectStatus(true)
                            preEnv:PlayAnimation(true)
                        end
                        ---刷新任务列表信息
                        self:FreshTaskListView()
                    end
                else
                    GameUtils.Toast(localize("还没有开放"))
                end
            elseif self.selectDayNum == #groups then
                local isFinalPrizeDrawn = checkNumber(beginnerMgr:GetHomeDojo().drawnFinalPrize) == 1
                if isFinalPrizeDrawn then
                    GameUtils.Toast(localize("奖励已领取"))
                    return
                elseif not beginnerMgr:IsTaskCompleted() then
                    GameUtils.Toast(localize("为满足领取条件"))
                    return
                end
                ---最后一天情况
                GameUtils.Request(Interfaces.ActivityBeginnerDrawFinalReward, { prizeId = 1 }, function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local data = response.data
                        GoodsUtils.DrawRewards(data.rewards)
                        beginnerMgr:GetHomeDojo().drawnFinalPrize = 1
                        self:FreshRedPoint()
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                        self:FreshTaskView()
                    end
                end)
            end
        end)
    end

    --刷新任务列表
    self:FreshTaskListView()
end

function BeginnerAssembleTaskPanel:FreshTaskListView()
    CfUtils.SetActive(self.MainTaskCellGroup, true)
    local beginnerMgr = BeginnerUtils.GetBeginnerMgr()
    local tasks = beginnerMgr:GetTasksByGroup(self.selectDayNum)
    print("===>>", table.dump(tasks, false, 3))
    self.tasksOfDay = tasks
    ---@endregion
    self:SetSevenContentCellNode(self.MainTaskCellGroup, self.tasksOfDay[1])
    table.remove(self.tasksOfDay, 1)
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#self.tasksOfDay, Bind(self, self.OnGetItemByIndexSeven))
    else
        GameUtils.ReloadData(self.ListView, #self.tasksOfDay)
    end
end

function BeginnerAssembleTaskPanel:SetSevenContentCellNode(cell, data, isSub)
    ---@type BeginnerAssembleTaskCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.Activity.BeginnerAssemble.Cell.BeginnerAssembleTaskCellNode")
    if nodeEnv then
        nodeEnv:FreshBaseUI(data, isSub)
        nodeEnv:SetBtnCallBackJump(function()
            local isCompleted = data.progress >= data.taskContentNum
            if not isCompleted then
                if checkNumber(data.taskVo.openType) == 0 then
                    return
                end
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                local row = goodsConfMgr:GetJumpModuleRow(data.taskVo.openType)
                goodsConfMgr:ExecuteJump(row, {})
            end
        end)
        nodeEnv:SetBtnCallBackGet(function()
            local isCompleted = data.progress >= data.taskContentNum
            local isDrawn = data.hasDrawn == 1
            if isCompleted and (not isDrawn) then
                GameUtils.Request(
                        Interfaces.ActivityBeginnerDrawTask,
                        { taskId = data.id },
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                local responseData = response.data
                                BeginnerUtils.GetBeginnerMgr():UpdateTaskStatus(self.selectDayNum, data.id, 1)
                                xTry(function()
                                    self:FreshRedPoint()
                                end)
                                local rewards = checkTable(responseData.rewards)
                                GoodsUtils.DrawRewards(rewards)
                                local targetId = 0
                                for _, v in pairs(rewards) do
                                    local goodsId = checkNumber(v.goodsId)
                                    if GoodsUtils.GetIdType(goodsId) == Constants.IDType.GoodsLoadingType then
                                        targetId = goodsId
                                        break
                                    end
                                end
                                if checkNumber(targetId) > 0 then
                                    print("===>>", targetId)
                                    if GoodsUtils.GetThingNo(targetId) <= 0 then
                                        return
                                    end
                                    ---@type GoodsLoadingVo
                                    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6588, "GoodsLoadingVo", targetId)
                                    local cg = vo.cg
                                    CfUtils.DialogOpen(Constants.UITypeIds.CgPreviewDialog, { cg = cg, cb = function()
                                        UIModule.OpenDialog(
                                                {
                                                    id = Constants.UITypeIds.UICommonRewardPop,
                                                    parameters = { rewards = rewards }
                                                }
                                        )
                                    end })
                                else
                                    UIModule.OpenDialog(
                                            {
                                                id = Constants.UITypeIds.UICommonRewardPop,
                                                parameters = { rewards = rewards }
                                            }
                                    )
                                end
                                self:FreshTaskView()
                            end
                        end
                )
            end
        end)
    end
end

---选择七天任务当前天的所有任务单元
function BeginnerAssembleTaskPanel:OnGetItemByIndexSeven(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("MainTaskCellGroup")
    local luaIndex = index + 1
    local data = self.tasksOfDay[luaIndex]
    self:SetSevenContentCellNode(cell, data, true)
    return cell
end

